_ZQ_VERSIONS = {
    'right': 'def average_cost(fills, fee):\n    shares = sum(s for s, p in fills)\n    paid = sum(s * p for s, p in fills) + fee * len(fills)\n    return paid / shares\n',
    'right_running': 'def average_cost(fills, fee):\n    held, avg = 0, 0.0\n    for s, p in fills:\n        held += s\n        avg += (s * p + fee - s * avg) / held\n    return avg\n',
    'right_exact': 'from fractions import Fraction\n\n\ndef average_cost(fills, fee):\n    paid = sum(Fraction(s) * Fraction(p) for s, p in fills) + Fraction(fee) * len(fills)\n    return float(paid / sum(Fraction(s) for s, p in fills))\n',
