import ast as _za, contextlib as _zc, io as _zio

_ZQ_SEEN = {}


def _zq_fn(nodeid):
    # test_mine.py::test_x[row] -> test_x
    return nodeid.split("::")[-1].split("[")[0]


def _zq_binds(node, name):
    if isinstance(node, (_za.FunctionDef, _za.AsyncFunctionDef, _za.ClassDef)):
        return node.name == name
    if isinstance(node, (_za.Assign, _za.AnnAssign)):
        targets = node.targets if isinstance(node, _za.Assign) else [node.target]
        return any(isinstance(t, _za.Name) and t.id == name for t in targets)
    return False


def _zq_source(name):
    # the learner's file, with the version under test in place of their own function
    if _ZQ_MODE == "module" or name == "own":
        return __learner_source__
    tree = _za.parse(__learner_source__)
    tree.body = _za.parse(_ZQ_VERSIONS[name]).body + [n for n in tree.body if not _zq_binds(n, _ZQ_FUNCTION)]
    return _za.unparse(tree)


def _zq_pytest(name, order="file", show=False):
    # run real pytest on the learner's file with one version of the function under test
    if _ZQ_MODE == "module":
        with open(_ZQ_MODULE + ".py", "w") as f:
            f.write(_ZQ_VERSIONS[name])
        _zs.modules.pop(_ZQ_MODULE, None)
    with open("test_mine.py", "w") as f:
        f.write(_zq_source(name))
    _zs.modules.pop("test_mine", None)
    _zil.invalidate_caches()
    seen, calls = {}, {}

    class _Watch:
        def pytest_collection_modifyitems(self, items):
            if order == "reverse":
                items.reverse()

        @_zpt.hookimpl(tryfirst=True)
        def pytest_runtest_setup(self, item):
            m = _zs.modules.get(_ZQ_MODULE)
            if m is not None:
                m._zq_calls = 0

        def pytest_runtest_logreport(self, report):
            was = seen.get(report.nodeid, "passed")
            if report.failed:
                was = "failed"
            elif report.skipped and was == "passed":
                was = "skipped"
            seen[report.nodeid] = was
            if report.when == "teardown":
                calls[report.nodeid] = getattr(_zs.modules.get(_ZQ_MODULE), "_zq_calls", 0)

    args = ["-q", "-p", "no:cacheprovider", "test_mine.py"]
    if show:
        code = _ZQ_MAIN(args, plugins=[_Watch()])
    else:
        with _zc.redirect_stdout(_zio.StringIO()), _zc.redirect_stderr(_zio.StringIO()):
            code = _ZQ_MAIN(args, plugins=[_Watch()])
    return int(code), seen, calls


def _zq_result(name, order="file"):
    key = (__learner_source__, name, order)
    if key not in _ZQ_SEEN:
        _ZQ_SEEN[key] = _zq_pytest(name, order)
    return _ZQ_SEEN[key]


