    return sorted({_zq_fn(n) for n in _zq_result(_ZQ_SHOWN)[1]})


def weak():
    """Your tests that never fail on the versions in _ZQ_WEAK_AGAINST."""
    failed = {_zq_fn(n) for v in _ZQ_WEAK_AGAINST for n, o in _zq_result(v)[1].items() if o == "failed"}
    return [t for t in names() if t not in failed]


def few(least=5):
